def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Calculate the maximum occupied volume by any subset of the items
    max_occupied_volume = 0
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            dp[j] = max(dp[j], dp[j - i] + volumes[i - 1])
            if dp[j] > max_occupied_volume:
                max_occupied_volume = dp[j]

    # Return the difference between the box's total capacity and the maximum occupied volume
    return V - max_occupied_volume

