def sort_students(student_scores):
    # Step 1: Sort the students by their total score in descending order
    sorted_students = sorted(student_scores, key=lambda x: x[1], reverse=True)

    # Step 2: If there are any students with the same total score, sort them by their Chinese score in descending order
    for i in range(len(sorted_students)):
        if i > 0 and sorted_students[i][1] == sorted_students[i - 1][1]:
            sorted_students[i:i + 1] = sorted(sorted_students[i:i + 1], key=lambda x: x[2], reverse=True)

    # Step 3: If there are any students with the same total score and Chinese score, sort them by their student number in ascending order
    for i in range(len(sorted_students)):
        if i > 0 and sorted_students[i][1] == sorted_students[i - 1][1] and sorted_students[i][2] == sorted_students[i - 1][2]:
            sorted_students[i:i + 1] = sorted(sorted_students[i:i + 1], key=lambda x: x[0])

